const isTodo = s => !s || /\[\[/.test(s);
const plain = s => String(s).replace(/\[\[|\]\]/g, "");
const href = u => /^(https?:|mailto:|tel:|\/)/i.test(u) ? u : "https://" + u;
const linkOrTodo = (u, label) => isTodo(u) ? fmt(u || "[[Add]]") : `<a class="v" href="${esc(href(u))}" target="_blank" rel="noopener">${esc(label || u.replace(/^https?:\/\//,"").replace(/\/$/,""))}</a>`;
const mailOrTodo = e => isTodo(e) ? fmt(e || "[[Add]]") : `<a class="v" href="mailto:${esc(e)}">${esc(e)}</a>`;
const telOrTodo = p => isTodo(p) ? fmt(p || "[[Add]]") : `<a class="v" href="tel:${esc(p.replace(/[^\d+]/g,""))}">${esc(p)}</a>`;
const I = d => `<svg class="i" viewBox="0 0 24 24" aria-hidden="true">${d}</svg>`;
