async function copy(text,msg){
  try{await navigator.clipboard.writeText(text)}
  catch(e){const a=document.createElement("textarea");a.value=text;a.style.cssText="position:fixed;opacity:0";document.body.appendChild(a);a.select();try{document.execCommand("copy")}catch(_){}a.remove()}
  toast(msg||"Copied");
}
function wrapSeg(el){
  if(el.parentElement.classList.contains("segbar"))return;
  const bar=document.createElement("div");bar.className="segbar";
  el.parentNode.insertBefore(bar,el);
  const l=document.createElement("button"),r=document.createElement("button");
  l.type=r.type="button";l.className=r.className="segarr";
  l.innerHTML=ICON.left;r.innerHTML=ICON.right;
  l.setAttribute("aria-label","Show options on the left");r.setAttribute("aria-label","Show options on the right");
  bar.append(l,el,r);
  const step=d=>el.scrollBy({left:d*Math.max(160,el.clientWidth*.6),behavior:"smooth"});
  l.addEventListener("click",()=>step(-1));r.addEventListener("click",()=>step(1));
  const sync=()=>{
    bar.classList.toggle("over",el.scrollWidth>el.clientWidth+2);
    l.disabled=el.scrollLeft<=2;r.disabled=el.scrollLeft+el.clientWidth>=el.scrollWidth-2;
  };
  el._sync=sync;
  el.addEventListener("scroll",sync,{passive:true});
  addEventListener("resize",sync);
  if("ResizeObserver" in window)new ResizeObserver(sync).observe(el);
}
document.addEventListener("click",async e=>{
  const b=e.target.closest("[data-copy]");if(!b)return;
  e.preventDefault();
  await copy(b.dataset.copy,b.dataset.msg||"Copied");
  const o=b.innerHTML;b.innerHTML=ICON.check;setTimeout(()=>{b.innerHTML=o},1400);
});
const cpBtn=(text,msg,cls)=>`<button type="button" class="${cls||"sm cpy"}" data-copy="${esc(text)}" data-msg="${esc(msg)}" aria-label="${esc(msg)}" title="${esc(msg)}">${ICON.copy}</button>`;
function tabs(el, items, current, onPick){
  wrapSeg(el);
  const prev=el.scrollLeft;
  el.innerHTML = items.map(([v,l,n])=>`<button type="button" role="tab" aria-selected="${v===current}" data-v="${esc(v)}">${esc(l)}${n!=null?`<i>${n}</i>`:""}</button>`).join("");
  $$("button",el).forEach(b=>b.addEventListener("click",()=>onPick(b.dataset.v)));
  el.scrollLeft=prev;
  const sel=$('[aria-selected="true"]',el);
  requestAnimationFrame(()=>{
    if(sel)el.scrollTo({left:sel.offsetLeft-el.clientWidth/2+sel.clientWidth/2,behavior:"smooth"});
    if(el._sync)el._sync();
  });
}

/* ---------- moving strip (marquee) ---------- */
function createMarquee(root,opt){
  const track=$(".mtrack",root);
  const st={x:0,period:0,w:0,hover:false,drag:null,holds:new Set(),running:false,inView:false,last:0,items:[],wire:null};
  function build(){
    st.holds.clear();st.x=0;track.style.transform="";
    const items=st.items,n=items.length;
    if(!n){track.innerHTML=`<div class="empty-note">Nothing added here yet.</div>`;st.period=0;return}
    track.innerHTML=items.join("");
    if(!root.clientWidth){st.period=0;st.w=0;return}          // hidden for now: build the strip when it becomes visible
    const cw=root.clientWidth,setW=track.scrollWidth||1;
    const reps=Math.max(2,Math.ceil(cw/setW)+1);
    track.innerHTML=Array(reps).fill(items.join("")).join("");
    const els=$$(":scope > .mitem",track);
    st.period=els[n]?els[n].offsetLeft-els[0].offsetLeft:setW;st.w=cw;
    els.forEach((el,k)=>{
      if(k>=n){el.setAttribute("aria-hidden","true");$$("a,button",el).forEach(b=>b.tabIndex=-1)}
      if(st.wire)st.wire(el,k%n);
    });
    track.classList.remove("mf");void track.offsetWidth;track.classList.add("mf");
  }
  function tick(t){
    if(!st.running)return;
    const dt=Math.min(t-st.last,50);st.last=t;
    if(st.period){
      if(!st.drag&&!st.hover&&!st.holds.size)st.x+=opt.dir*opt.speed*dt/1000;
      while(st.x<=-st.period)st.x+=st.period;
      while(st.x>0)st.x-=st.period;
      track.style.transform=`translate3d(${st.x.toFixed(2)}px,0,0)`;
    }
    requestAnimationFrame(tick);
  }
  const start=()=>{if(st.running||!st.inView||document.hidden)return;st.running=true;st.last=performance.now();requestAnimationFrame(tick)};
  const stop=()=>{st.running=false};
  new IntersectionObserver(e=>{st.inView=e[0].isIntersecting;st.inView?start():stop()}).observe(root);
  document.addEventListener("visibilitychange",()=>document.hidden?stop():start());
  const endDrag=()=>{if(st.drag&&st.drag.moved){root._suppress=true;setTimeout(()=>{root._suppress=false},80)}st.drag=null};
  root.addEventListener("pointerenter",e=>{if(e.pointerType==="mouse")st.hover=true});
  root.addEventListener("pointerleave",()=>{st.hover=false;endDrag()});
  root.addEventListener("pointerdown",e=>{root._pt=e.pointerType;if(e.button>0)return;st.drag={sx:e.clientX,x0:st.x,moved:false}});
  root.addEventListener("pointermove",e=>{if(!st.drag)return;const dx=e.clientX-st.drag.sx;if(Math.abs(dx)>6)st.drag.moved=true;if(st.drag.moved)st.x=st.drag.x0+dx});
  root.addEventListener("pointerup",endDrag);
  root.addEventListener("pointercancel",()=>{st.drag=null});
  root.addEventListener("click",e=>{if(root._suppress){e.stopPropagation();e.preventDefault()}},true);
  if("ResizeObserver" in window)new ResizeObserver(()=>{if(st.items.length&&Math.abs(root.clientWidth-st.w)>40)build()}).observe(root);
  return {set(items,wire){st.items=items;st.wire=wire;build()},hold(k,on){on?st.holds.add(k):st.holds.delete(k)}};
}

/* ---------- editable categories (tabs) ---------- */
const catNames=(key,derive)=>{
  const c=(DATA.categories||{})[key];
  if(Array.isArray(c)&&c.length)return c.filter(x=>x&&!(typeof x==="object"&&x.off)).map(x=>typeof x==="string"?x:x.name).filter(Boolean);
  return derive?derive():[];
};

