let recType="All",recTimer=null,recIO=null;
const REC_INT=6500;
function renderRecs(){
  clearTimeout(recTimer);
  const types=catNames("recommendations",()=>["Professional","Academic"]);
  tabs($("#recTabs"),[["All","All",DATA.recommendations.length],...types.map(t=>[t,t,DATA.recommendations.filter(r=>r.type===t).length])],recType,v=>{recType=v;renderRecs()});
  const list=DATA.recommendations.filter(r=>recType==="All"||r.type===recType),n=list.length,box=$("#recBox");
  box.onmouseenter=box.onmouseleave=null;
  if(!n){box.innerHTML=`<div class="empty-note">No recommendations added here yet.</div>`;return}
  box.innerHTML=(n>1?`<div class="rprog"><i></i></div>`:"")+`<div class="rvp fade"><div class="rtrack">${list.map((r,k)=>
    `<article class="rcard ${k===0?"on":""}"><blockquote>${fmt(r.quote)}</blockquote><div class="who"><b>${fmt(r.name)}</b>${[r.position,r.org].filter(Boolean).length?`<span>${[r.position,r.org].filter(Boolean).map(fmt).join(", ")}</span>`:""}${r.relation?`<span>${fmt(r.relation)}</span>`:""}${r.email?`<span class="rem">${ICON.mail}${mailOrTodo(r.email)}</span>`:""}<span class="tagpill">${r.type?esc(r.type)+" ":""}recommendation</span></div>${r.reply?`<div class="rreply"><b>My reply</b><p>${fmt(r.reply)}</p></div>`:""}</article>`).join("")}</div></div>`+
    (n>1?`<div class="rctl"><button type="button" class="sm rp" aria-label="Previous recommendation">${ICON.left}Previous</button><div class="dots">${list.map((_,k)=>`<i class="${k===0?"on":""}" data-k="${k}"></i>`).join("")}</div><button type="button" class="sm rn" aria-label="Next recommendation">Next${ICON.right}</button></div>`:"");
  if(n<2)return;
  const track=$(".rtrack",box),vp=$(".rvp",box),bar=$(".rprog i",box);let k=0,hover=false,visible=false,sx=null;
  const run=()=>{clearTimeout(recTimer);bar.classList.remove("run");if(hover||!visible||document.hidden)return;void bar.offsetWidth;bar.classList.add("run");recTimer=setTimeout(()=>go(k+1),REC_INT)};
  const go=to=>{k=(to+n)%n;track.style.transform=`translateX(${-100*k}%)`;$$(".rcard",box).forEach((c,x)=>c.classList.toggle("on",x===k));$$(".dots i",box).forEach((d,x)=>d.classList.toggle("on",x===k));run()};
  $(".rp",box).addEventListener("click",()=>go(k-1));
  $(".rn",box).addEventListener("click",()=>go(k+1));
  $$(".dots i",box).forEach(d=>d.addEventListener("click",()=>go(+d.dataset.k)));
  vp.addEventListener("pointerdown",e=>{sx=e.clientX});
  vp.addEventListener("pointerup",e=>{if(sx==null)return;const dx=e.clientX-sx;sx=null;if(Math.abs(dx)>40)go(k+(dx<0?1:-1))});
  vp.addEventListener("pointercancel",()=>{sx=null});
  box.onmouseenter=()=>{hover=true;run()};
  box.onmouseleave=()=>{hover=false;run()};
  if(recIO)recIO.disconnect();
  recIO=new IntersectionObserver(e=>{visible=e[0].isIntersecting;run()},{threshold:.3});
  recIO.observe(box);
  document.addEventListener("visibilitychange",run);
}
renderRecs();
