/* ---------- message / recommendation form ---------- */
function openForm(kind){
  const rec=kind==="recommendation",opened=Date.now();
  let dlg=$("#fm");if(dlg)dlg.remove();
  dlg=document.createElement("dialog");dlg.id="fm";dlg.className="fmd";
  const types=catNames("recommendations",()=>["Professional","Academic"]);
  dlg.innerHTML=`<form novalidate>
    <h3>${rec?"Write a recommendation":"Send a message"}</h3>
    <p class="fnote">${rec?"It will be shown on this website with your name. Your email stays private.":"I will reply by email."}</p>
    <label>Your name<input name="name" autocomplete="name" required maxlength="120"></label>
    <label>Your email${rec?" (not shown)":""}<input name="email" type="email" autocomplete="email" required maxlength="200"></label>
    ${rec?`<label>Your position<input name="position" maxlength="160"></label><label>Your organisation<input name="org" maxlength="160"></label><label>How do we know each other?<input name="relation" maxlength="160"></label>${types.length?`<label>Type<select name="type">${types.map(t=>`<option>${esc(t)}</option>`).join("")}</select></label>`:""}`:""}
    <label>${rec?"Your recommendation":"Message"}<textarea name="text" required maxlength="${rec?2000:3000}"></textarea></label>
    ${rec?`<label class="fchk"><input type="checkbox" name="showEmail"> Also show my email on the website</label>`:""}
    <input class="hp" name="website" tabindex="-1" autocomplete="off" aria-hidden="true">
    <p class="ferr" role="alert"></p>
    <div class="frow"><button type="button" class="sm" data-x>Cancel</button><button type="submit" class="btn deep">Send</button></div>
  </form>`;
  document.body.appendChild(dlg);
  const form=$("form",dlg),errEl=$(".ferr",dlg);
  let published=false;
  const close=()=>{dlg.close();if(published)location.reload()};
  $("[data-x]",dlg).addEventListener("click",close);
  dlg.addEventListener("click",e=>{if(e.target===dlg)close()});
  dlg.addEventListener("cancel",()=>{if(published)setTimeout(()=>location.reload(),0)});
  const send=async()=>{
    errEl.textContent="";
    const b=Object.fromEntries(new FormData(form).entries());b.showEmail=!!b.showEmail;b.t=opened;
    const btn=$("button.btn",form);btn.disabled=true;btn.textContent="Sending";
    try{
      const r=await fetch(rec?"/api/recommend":"/api/submit",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(rec?b:Object.assign(b,{kind}))});
      const j=await r.json().catch(()=>({}));
      if(!r.ok)throw new Error(j.error||"Could not send. Please try again.");
      published=!!(rec&&j.published);
      form.innerHTML=`<h3>Thank you</h3><p class="fnote">${rec?(published?"Your recommendation is now on the page.":"Your recommendation was received. It will appear after I have seen it."):"Your message was received. I will reply by email."}</p><div class="frow"><button type="button" class="btn deep" data-x>${published?"See it on the page":"Close"}</button></div>`;
      $("[data-x]",form).addEventListener("click",close);
    }catch(x){errEl.textContent=x.message;btn.disabled=false;btn.textContent="Send"}
  };
  form.addEventListener("submit",e=>{e.preventDefault();send()});
  $('button[type="submit"]',form).type="button";
  $('button[type="button"].btn',form).addEventListener("click",send);
  $$("input:not([type=checkbox])",form).forEach(i=>i.addEventListener("keydown",e=>{if(e.key==="Enter"){e.preventDefault();send()}}));
  if(dlg.showModal)dlg.showModal();else dlg.setAttribute("open","");
}

/* ---------- local time in Dhaka, compared with the visitor ---------- */
(function(){
  const el=$("#ltime");if(!el)return;
  function tick(){
    let t;try{t=new Intl.DateTimeFormat("en-GB",{timeZone:"Asia/Dhaka",weekday:"short",hour:"numeric",minute:"2-digit",hour12:true}).format(new Date())}catch(e){return}
    const diff=360+new Date().getTimezoneOffset();   /* Dhaka is UTC+6 all year */
    const a=Math.abs(diff),hh=Math.floor(a/60),mm=a%60;
    const gap=(hh?hh+" h":"")+(mm?(hh?" ":"")+mm+" min":"");
    el.textContent=`${t}, Dhaka (GMT+6). `+(diff===0?"Same time as you.":`${gap} ${diff>0?"ahead of":"behind"} you.`);
  }
  tick();setInterval(tick,30000);
})();

